int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *pair_start = in;
    size_t pair_count = 0;

    while (pair_count < max_pairs && *pair_start != '\0') {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair_start);
        keys_out[pair_count] = malloc(klen + 1);
        if (!keys_out[pair_count]) return -1;
        strncpy(keys_out[pair_count], pair_start, klen);
        keys_out[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++; // Skip leading spaces

        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) {
                for (size_t i = 0; i <= pair_count; i++) free(keys_out[i]);
                return -1; // No closing quote found
            }
            size_t vlen = (size_t)(quote_end - val_start - 1);
            vals_out[pair_count] = malloc(vlen + 1);
            if (!vals_out[pair_count]) {
                for (size_t i = 0; i <= pair_count; i++) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[pair_count], val_start + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
        } else {
            const char *space_pos = strchr(val_start, ' ');
            if (!space_pos) space_pos = eq + strlen(eq); // If no space, go to end of string
            size_t vlen = (size_t)(space_pos - val_start);
            vals_out[pair_count] = malloc(vlen + 1);
            if (!vals_out[pair_count]) {
